<?php
require_once __DIR__.'/../app/bootstrap_financial.php';redirectIfNotLoggedIn();$userId=(int)$_SESSION['user_id'];$start=$_GET['start']??gmdate('Y-m-01');$end=$_GET['end']??gmdate('Y-m-d');$startDate=DateTimeImmutable::createFromFormat('!Y-m-d',$start);$endDate=DateTimeImmutable::createFromFormat('!Y-m-d',$end);if(!$startDate||!$endDate||$startDate>$endDate){http_response_code(422);exit('Invalid statement period.');}$stmt=$pdo->prepare('SELECT reference,type,amount_cents,fee_cents,status,description,created_at FROM financial_transactions WHERE user_id=? AND created_at>=? AND created_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY created_at');$stmt->execute([$userId,$start,$end]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="valtoria-statement-'.$start.'-'.$end.'.csv"');$out=fopen('php://output','wb');fputcsv($out,['Valtoria Bank statement']);fputcsv($out,['Period',$start.' to '.$end]);fputcsv($out,['Currency','USD']);fputcsv($out,[]);fputcsv($out,['Reference','Type','Amount USD','Fee USD','Status','Description','Created UTC']);foreach($stmt as $row)fputcsv($out,[$row['reference'],$row['type'],Money::decimal((int)$row['amount_cents']),Money::decimal((int)$row['fee_cents']),$row['status'],$row['description'],$row['created_at']]);fclose($out);exit;
